EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base SYRK kernel:
#   C := beta * C + alpha * A * A^T
# Only the lower triangular part of C (j <= i) is updated,
# matching the PolyBench syrk kernel.
@proc
def kernel_syrk_base(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
):
    for i in seq(0, n):
        # Scale the lower triangular part of row i by beta.
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

        # Rank-k update: C[i, j] += alpha * A[i, k] * A[j, k]
        # We cache A[i, k] in a scalar to avoid reloading it for every j.
        for k in seq(0, m):
            a_ik: DATA_TYPE
            a_ik = A[i, k]
            for j in seq(0, i + 1):
                C[i, j] += alpha * a_ik * A[j, k]

# Start from the base kernel and apply scheduling transformations.
kernel_syrk_opt = kernel_syrk_base

# 1. Parallelize the outer loop over i.
#    Each iteration updates a distinct row i of the lower triangle of C,
#    so there are no cross-iteration dependencies on C.
i_loop = kernel_syrk_opt.find_loop("i")
kernel_syrk_opt = parallelize_loop(kernel_syrk_opt, i_loop)

