#    K_TILE is a compile-time tuning parameter; 32 is a reasonable default
#    for modern x86 L1/L2 cache sizes.
K_TILE = 32
k_loop = kernel_syrk_opt.find_loop("k")
kernel_syrk_opt = divide_loop(kernel_syrk_opt, k_loop, K_TILE, ("ko", "ki"), tail="guard")

# 3. Expose the optimized kernel under the name expected by the C driver.
kernel_syrk = rename(kernel_syrk_opt, "kernel_syrk")
